from solution import shortest_path_length

def test_shortest_path_length():
    graph = {0: [1, 2], 1: [0, 3], 2: [0, 3], 3: [1, 2]}
    assert shortest_path_length(graph, 0, 3) == 2
    assert shortest_path_length(graph, 0, 1) == 1
    assert shortest_path_length(graph, 3, 0) == 2
    assert shortest_path_length(graph, 1, 2) == 2
    graph = {0: [1], 1: [0, 2], 2: [1]}
    assert shortest_path_length(graph, 0, 2) == 2
    assert shortest_path_length(graph, 2, 0) == 2
    assert shortest_path_length(graph, 0, 3) == -1
    assert shortest_path_length(graph, 1, 1) == 0
    graph = {0: [1], 1: [0]}
    assert shortest_path_length(graph, 0, 1) == 1
    assert shortest_path_length(graph, 1, 0) == 1
    graph = {0: [], 1: [2], 2: [1]}
    assert shortest_path_length(graph, 0, 1) == -1
    assert shortest_path_length(graph, 1, 0) == -1

def test_empty_graph():
    assert shortest_path_length({}, 0, 1) == -1

def test_single_node_graph():
    graph = {0: []}
    assert shortest_path_length(graph, 0, 0) == 0
    assert shortest_path_length(graph, 0, 1) == -1
