def move_character(directions):
    """
    Move the character based on a set of directions from the user.

    Parameters:
    directions (str): Space-separated string containing the directions to move. 
                      Valid directions are "north", "east", "south", "west".

    Returns:
    dict: A dictionary showing the final position of the character.
    """
    position = {'x': 0, 'y': 0}

    for direction in directions.split():
        if direction == "north":
            position['y'] += 1
        elif direction == "east":
            position['x'] += 1
        elif direction == "south":
            position['y'] -= 1
        elif direction == "west":
            position['x'] -= 1
        else:
            raise ValueError(f"Invalid direction: {direction}")

    return position

```

