def fibonacci_sequence(n):
    """
    Returns a list containing the Fibonacci sequence up to a given number n.
    """
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]

    sequence = [0, 1]
    while True:
        next_value = sequence[-1] + sequence[-2]
        if next_value <= n:
            sequence.append(next_value)
        else:
            break
    return sequence

```

