def count_long_words(words):
    """
    Returns a dictionary containing the count of each word in the list
    that has more than 3 letters.
    """
    word_count = {}

    for word in words:
        if len(word) > 3:
            if word in word_count:
                word_count[word] += 1
            else:
                word_count[word] = 1

    return word_count

```

