def shortest_unique_string(strings):
    """
    Returns the shortest string from the array that doesn't include any repeated characters.
    If there are multiple, return the first one found.
    """
    def has_unique_chars(s):
        return len(s) == len(set(s))

    shortest_string = None
    for s in strings:
        if has_unique_chars(s):
            if shortest_string is None or len(s) < len(shortest_string):
                shortest_string = s

    return shortest_string

```

