def sum_of_odd_digits(n):
    """
    Recursively calculates the sum of all odd digits in a given non-negative integer.

    :param n: non-negative integer
    :return: sum of odd digits
    """
    if n == 0:
        return 0

    current_digit = n % 10
    if current_digit % 2 != 0:
        return current_digit + sum_of_odd_digits(n // 10)
    else:
        return sum_of_odd_digits(n // 10)

```

