def char_frequency(input_string):
    """
    Returns a list of tuples with each character in the input string and its frequency count.
    Case-sensitive (i.e., 'A' and 'a' are considered different characters).
    """
    freq_dict = {}
    for char in input_string:
        if char in freq_dict:
            freq_dict[char] += 1
        else:
            freq_dict[char] = 1
    return list(freq_dict.items())

```

