def fibonacci_recursion(n):
    """
    Generates the fibonacci sequence using recursion.
    """
    def helper(n, a=0, b=1):
        if n == 0:
            return []
        elif n == 1:
            return [a]
        else:
            return [a] + helper(n-1, b, a+b)

    return helper(n)

```

