def flatten_dictionary(input_dict: dict, delimiter: str = '.') -> dict:
    """
    Flattens a nested dictionary into a single-level dictionary.

    Arguments:
    input_dict -- The dictionary to be flattened.
    delimiter -- The string to be used as a separator for keys.

    Returns:
    A flattened dictionary.
    """
    def _flatten(current_dict, parent_key=''):
        items = []
        for k, v in current_dict.items():
            new_key = f"{parent_key}{delimiter}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(_flatten(v, new_key).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return _flatten(input_dict)

```

