def sum_of_products(nested_list):
    """
    Returns the sum of products from nested lists.
    The function handles any number of nested levels in a list.
    """
    def product(lst):
        result = 1
        for item in lst:
            if isinstance(item, list):
                result *= product(item)
            else:
                result *= item
        return result

    def sum_products(lst):
        total = 0
        for item in lst:
            if isinstance(item, list):
                total += product(item)
            else:
                total += item
        return total

    return sum_products(nested_list)

```

