def simplify_path(path: str) -> str:
    """
    Simplifies a given Unix-style file path.
    """
    parts = path.split("/")
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    simplified_path = "/" + "/".join(stack)
    return simplified_path

```

