def recursive_power(base: float, exponent: int) -> float:
    """
    Compute the power of a base raised to an exponent using recursion.

    :param base: A float representing the base value.
    :param exponent: A non-negative integer representing the exponent value.
    :return: A float that is base raised to the power of exponent.
    """
    if not isinstance(base, (int, float)):
        raise ValueError("Base must be a number.")

    if not isinstance(exponent, int) or exponent < 0:
        raise ValueError("Exponent must be a non-negative integer.")

    if exponent == 0:
        return 1.0
    if exponent == 1:
        return base

    half_power = recursive_power(base, exponent // 2)
    if exponent % 2 == 0:
        return half_power * half_power
    else:
        return half_power * half_power * base

```

