def calculate_averages(data: dict) -> dict:
    """
    Calculate the averages of list values in the dictionary.

    Parameters:
    data (dict): A dictionary with strings as keys and lists of integers as values.

    Returns:
    dict: A dictionary with the same keys and the average of the corresponding values, or "N/A" for empty lists.
    """
    result = {}

    for key, values in data.items():
        if not isinstance(key, str):
            raise ValueError("All keys must be strings")
        if not isinstance(values, list):
            raise ValueError("All values must be lists of integers")

        if len(values) == 0:
            result[key] = "N/A"
        else:
            result[key] = sum(values) / len(values)

    return result

```

