def length_of_lis(nums):
    """
    Returns the length of the longest strictly increasing subsequence in the list of positive integers.

    Parameters:
    nums (list): A list of positive integers

    Returns:
    int: The length of the longest strictly increasing subsequence
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # dp[i] represents the length of the longest increasing subsequence that ends with nums[i]

    for i in range(n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

```

