from typing import List, Dict


def classify_weights(weights: List[float]) -> Dict[str, int]:
    """
    Classifies the given weights into 'Light', 'Medium', 'Heavy', and 'Very Heavy' categories.
    """
    categories = {
        'Light': 0,
        'Medium': 0,
        'Heavy': 0,
        'Very Heavy': 0
    }

    for weight in weights:
        if weight < 1:
            categories['Light'] += 1
        elif 1 <= weight < 10:
            categories['Medium'] += 1
        elif 10 <= weight < 25:
            categories['Heavy'] += 1
        else:
            categories['Very Heavy'] += 1

    return categories

```

