def process_data(data: list) -> dict:
    """
    Processes a list of tuples containing identifier (string) and value (integer).
    """
    result = {}

    for item in data:
        if not isinstance(item, tuple) or len(item) != 2:
            raise AssertionError("Invalid item encountered")

        identifier, value = item

        if not isinstance(identifier, str):
            raise TypeError("Invalid identifier: must be a string")
        if not isinstance(value, int):
            raise TypeError("Invalid value: must be an integer")

        if value < 0:
            continue

        if identifier == "STOP":
            break

        if identifier in result:
            result[identifier] += value
        else:
            result[identifier] = value

    return result

```

