def shift_characters(s):
    """
    Shift each alphabetic character to the next character in the alphabet,
    wrapping 'z' to 'a' and 'Z' to 'A'. Non-alphabetic characters remain unchanged.
    """
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            result.append(chr((ord(char) - ord('a') + 1) % 26 + ord('a')))
        elif 'A' <= char <= 'Z':
            result.append(chr((ord(char) - ord('A') + 1) % 26 + ord('A')))
        else:
            result.append(char)
    return ''.join(result)

```

