def count_pairs_with_sum(arr: list, target: int) -> int:
    """
    Returns the number of distinct pairs that sum up to the target integer.
    """
    counts = {}
    pair_count = 0

    # Count occurrences of each number
    for number in arr:
        counts[number] = counts.get(number, 0) + 1

    # Check for pairs that sum up to target
    for number in list(counts):
        complement = target - number
        if complement in counts:
            if number == complement:
                # Handling pairs with the same number (n, n)
                pair_count += counts[number] * (counts[number] - 1) // 2
            elif complement > number:
                # Only count each pair once (n, m) where n < m
                pair_count += counts[number] * counts[complement]

    return pair_count

```

