def has_three_consecutive_odds(nums):
    """
    Returns True if there are three consecutive odd numbers in the list, and False otherwise.
    """
    count = 0
    for num in nums:
        if num % 2 != 0:
            count += 1
            if count == 3:
                return True
        else:
            count = 0

    return False

```

